namespace ghidra.graph.job;



using org.jdesktop.animation.timing;
using org.jdesktop.animation.timing.interpolation;

using edu.uci.ics.jung.visualization;
using edu.uci.ics.jung.visualization.renderers;
using edu.uci.ics.jung.visualization.renderers.Renderer;
using ghidra.graph.viewer.edge;

public class EdgeHoverAnimator<V, E> : AbstractAnimator {

	private static readonly int MOTION_SPEED = 2000;
	private static readonly Supplier<Float> ANIMATED_DASHED_LINE_FLOAT_GIVER = () => {
		long currentTimeMillis = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
		return (MOTION_SPEED - (currentTimeMillis % MOTION_SPEED)) / (float) MOTION_SPEED;
	};

	private static readonly int SLEEP_AMOUNT_MILLISECONDS = 300;
	private static readonly int DURATION = 5000;
	private long lastPaintTime = Stopwatch.GetTimestamp();

	private VisualizationServer<V, E> primaryViewer;
	private VisualizationServer<V, E> satelliteViewer;

	private bool useAnimation;

	public EdgeHoverAnimator(VisualizationServer<V, E> primaryViewer,
			VisualizationServer<V, E> satelliteViewer, bool useAnimation) {
		this.primaryViewer = primaryViewer;
		this.satelliteViewer = satelliteViewer;
		this.useAnimation = useAnimation;
	}

	/* @Override */
	protected Animator createAnimator() {
		if (!useAnimation) {
			return null;
		}

		Animator newAnimator =
			PropertySetter.createAnimator(DURATION, this, "nextPaint", 0, DURATION);
		newAnimator.setAcceleration(0.0f);
		newAnimator.setDeceleration(0.8f);
		return newAnimator;
	}

	/* @Override */
	protected void finished() {
		paintDashedLineOnce();
	}

	public void setNextPaint(int nextPaint) {
		long currentTime = Stopwatch.GetTimestamp();
		long ellapsedMilliseconds = (currentTime - lastPaintTime) / 1000000;
		if (ellapsedMilliseconds > SLEEP_AMOUNT_MILLISECONDS) {
			lastPaintTime = currentTime;
			paintDashedLineOnce();
		}
	}

	private void paintDashedLineOnce() {
		float newPaintOffset = ANIMATED_DASHED_LINE_FLOAT_GIVER.get();
		updateRendererPaintOffset(primaryViewer, newPaintOffset);
		updateRendererPaintOffset(satelliteViewer, newPaintOffset);

		primaryViewer.repaint();
		satelliteViewer.repaint();
	}

	private void updateRendererPaintOffset(VisualizationServer<V, E> viewer, float newPaintOffset) {
		Renderer<V, E> renderer = viewer.getRenderer();
		Edge<V, E> edgeRenderer = renderer.getEdgeRenderer();
		if (!(edgeRenderer is VisualEdgeRenderer)) {
			return; // something is wrong here!
		}
		VisualEdgeRenderer<object,object> functionGraphEdgeRenderer =
			(VisualEdgeRenderer<object,object>) edgeRenderer;
		functionGraphEdgeRenderer.setDashingPatternOffset(newPaintOffset);
	}
}
